{
  "fragen": [
    {
      "felder": ["f3", "f4"],
      "frage": "Wie lautet der Nachname und das Geburtsdatum der Arbeitnehmerin oder des Arbeitnehmers? (Bitte Datum im Format TT.MM.JJJJ eintragen.)"
    },
    {
      "felder": ["f1", "f2"],
      "frage": "Gibt es ein Geschlecht anzugeben? (Frau, Mann oder divers)"
    },
    {
      "felder": ["f5", "f6", "f7"],
      "frage": "Wie lautet die vollständige Adresse (PLZ, Strasse, Ort) der Arbeitnehmerin oder des Arbeitnehmers?"
    },
    {
      "felder": ["f8"],
      "frage": "Wie lautet die E-Mail-Adresse der Arbeitnehmerin oder des Arbeitnehmers?"
    },
    {
      "felder": ["f9", "f10"],
      "frage": "Wie lautet der Firmenname der Arbeitgeberin oder des Arbeitgebers und wer ist die Kontaktperson?"
    },
    {
      "felder": ["f11", "f12"],
      "frage": "Wie lautet die Adresse der Arbeitgeberin oder des Arbeitgebers (PLZ, Strasse, Ort) und wie lautet die Telefonnummer?"
    },
    {
      "felder": ["f14", "f16", "f17"],
      "frage": "In welchem Jahr begann die Anstellung? Welche Funktion oder welchen ausgeübten Beruf hat die Person inne? Und wie viele Stunden pro Woche beträgt die Arbeitszeit (z. B. 40)?"
    },
    {
      "felder": ["f18", "f19", "f20"],
      "frage": "Arbeitet die Person in Vollzeit, Teilzeit oder mit einem anderen Pensum? Bitte geben Sie den Prozentsatz an (z. B. 80 %)."
    },
    {
      "felder": ["f22"],
      "frage": "Falls das Arbeitsverhältnis gekündigt wurde, bis wann läuft die Kündigungsfrist? (Bitte Datum eintragen)"
    },
    {
      "felder": ["f23", "f24", "f25"],
      "frage": "Was ist die Ursache der Arbeitsunfähigkeit? (Krankheit, Unfall oder Berufskrankheit)"
    },
    {
      "felder": ["f26", "f27"],
      "frage": "Basiert die Beurteilung auf einem Arbeitsplatzbeschrieb oder einem REP (Ressourcenorientiertes Eingliederungsprofil)? (Bitte ankreuzen)"
    },
    {
      "felder": ["f28", "f29"],
      "frage": "Wann wurde der Arbeitsplatzbeschrieb oder das REP erstellt? (Bitte Datum eintragen)"
    },
    {
      "felder": ["f30", "f31", "f32", "f33", "f34", "f35", "f36", "f37", "f38", "f39", "f40", "f41", "f42", "f43", "f44"],
      "frage": "Für welche Konsultationsdaten soll die Arbeitsunfähigkeit von 100 % bestätigt werden? Bitte geben Sie jeweils das Datum, den Beginn, das Ende, das Datum der nächsten Konsultation und den Platz für das Visum an."
    },
    {
      "felder": ["f45", "f46"],
      "frage": "Liegt eine arbeitsplatzbezogene Arbeitsunfähigkeit vor? (Ja oder Nein)"
    },
    {
      "felder": ["f47", "f48", "f49", "f50"],
      "frage": "Basiert die Beurteilung der Teilarbeitsfähigkeit auf einem Arbeitsplatzbeschrieb oder einem REP? (Bitte ankreuzen) Und wann wurde dieser erstellt? (Bitte Datum eintragen)"
    },
    {
      "felder": ["f51", "f52", "f53", "f54", "f55", "f56", "f57", "f58", "f60", "f61", "f62", "f63", "f64", "f65", "f66", "f67", "f68", "f69", "f70", "f71", "f72", "f73", "f74", "f75", "f76", "f77", "f78", "f79", "f80", "f81", "f82", "f83", "f84", "f85", "f86"],
      "frage": "Für welche Konsultationsdaten soll die Präsenzzeit (Stunden pro Tag), das Pensum in Prozent und die Leistungsfähigkeit in Prozent angegeben werden? Bitte geben Sie jeweils das Datum, die Stunden pro Tag, das Pensum in Prozent und die Leistungsfähigkeit in Prozent an."
    },
    {
      "felder": ["f87"],
      "frage": "Ab wann ist die vollständige Wiederaufnahme der Arbeit vorgesehen? (Bitte Datum eintragen)"
    },
    {
      "felder": ["f88", "f89"],
      "frage": "Ist ein Kontakt mit der Arbeitgeberin oder dem Arbeitgeber erwünscht? (Ja oder Nein)"
    },
    {
      "felder": ["f90"],
      "frage": "Wie lautet der Name der Ärztin oder des Arztes, der das Zeugnis ausstellt?"
    },
    {
      "felder": ["f91"],
      "frage": "Wann wird das Zeugnis ausgefüllt? (Bitte Datum eintragen)"
    },
    {
      "felder": ["f92"],
      "frage": "Bitte unterschreiben Sie das Zeugnis."
    },
    {
      "felder": ["f93"],
      "frage": "Gibt es noch Bemerkungen oder zusätzliche Informationen, die für die Beurteilung wichtig sind?"
    }
  ]
}
